def minimumTime(s: str) -> int:
    n = len(s)
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        if s[i] == '1':
            suffix[i] = min(suffix[i + 1] + 2, n - i)
        else:
            suffix[i] = suffix[i + 1]
    ans = suffix[0]
    pre = 0
    for i in range(n):
        if s[i] == '1':
            pre = min(pre + 2, i + 1)
        if pre + suffix[i + 1] < ans:
            ans = pre + suffix[i + 1]
    return ans
